	function downloadSvg () {
			const svg = generateSvg();

			const a = document.createElement('a');
			a.href = URL.createObjectURL(new Blob([svg.outerHTML], {type: "image/svg+xml"}))
			a.download = "gbl-logo.svg";

			a.style.display = "none";
			document.body.append(a);
			a.click();
			document.body.removeChild(a);
		}
	function downloadPng(width) {
			const svg = generateSvg();
			const logoElement = document.getElementById("logo-target").querySelector("div");
			const renderedWidth = logoElement.clientWidth;
			const renderedHeight = logoElement.clientHeight;
			svg.setAttribute("width", width.toString());
			svg.setAttribute("height", ((renderedHeight/renderedWidth)*width).toString());
			const canvas = document.getElementById("canvas");
			canvas.width = width;
			canvas.height = (renderedHeight/renderedWidth)*width;
			const img = new Image();
			const ctx = canvas.getContext("2d");
			const url = URL.createObjectURL(new Blob([svg.outerHTML], {type: "image/svg+xml"}))
			img.src = url;
			img.width = 100;
			img.height = 100;
			img.addEventListener("load", () => {
					ctx.drawImage(img, 0, 0);
					const png = canvas.toDataURL("image/png");
					const a = document.createElement('a');
					a.href = png;
					a.download = "gbl-logo.png";
					a.style.display = "none";
					document.body.append(a);
					a.click();
					document.body.removeChild(a);
				});

		}
	function generateSvg() {
			console.log(svgIndex)
			const svg = svgTemplates[svgIndex].querySelector("svg").cloneNode(true);
			const logoElement = document.getElementById("logo-target").querySelector("div");

			svg.querySelector("g").attributes.fill.value = document.getElementById("fgip").value;
			svg.querySelector("rect").attributes.fill.value = document.getElementById("transpip").checked ? "transparent" : document.getElementById("bgip").value;

			const width = logoElement.clientWidth;
			const height = logoElement.clientHeight;
			const padding = parseInt(document.getElementById("padip").value);

			svg.querySelector("rect").attributes.width.value = width;
			svg.querySelector("rect").attributes.height.value = height;

			svg.attributes.viewBox.value = `0 0 ${width} ${height}`;

			const transform = svg.querySelector("#content").getAttribute("transform");
			svg.querySelector("#content").setAttribute("transform", `translate(${padding},${padding}) ${transform}`);

			return svg;
		}
